mapper.select:
select a.*,IF(c.ID is not null,c.`NAME`,a.orgName) as orgName, IF(d.ID is not null,d.`NAME`,a.position) as `position` from (select '总部' as userType, ID as id,`NAME` as name,DEPT_ID as orgId,DUTY_ID as positionId,`STATUS` as status,DEPT as orgName,DUTY as `position`, SEX as sex,ID_NUMBER as idCardNumber,BIRTH as birthDay,PHONE as phone,HIRE_DATE as hireDate,POSITIVE_TIME as positiveTime, USER_ID as userId,LEAVE_DATE as leaveDate,HIGHEST_EDUCATION as education,GRADUATE_SCHOOL as college,MAJOR as major, GREATEST(IFNULL(FIRST_GRADUATE_DATE,''),IFNULL(SECOND_GRADUATE_DATE,''),IFNULL(THIRD_GRADUATE_DATE,'')) as gradTime, null as certLevel,null as certMajor from PERSONNEL where DELETE_FLAG = 'NOT_DELETE' union all select '分公司' as userType, ID as id,`NAME` as name,DEPT_ID as orgId,DUTY_ID as positionId,HR_STATUS as status,DEPT as orgName,DUTY as `position`, SEX as sex,ID_NUMBER as idCardNumber,BIRTH as birthDay,PHONE as phone,HIRE_DATE as hireDate,POSITIVE_TIME as positiveTime, null as userId,RESIGNATION_TIME as leaveDate,HIGHEST_EDUCATION as education,GRADUATE_SCHOOL as college,MAJOR as major, null as gradTime,HIGH_TITLE_LEVER as certLevel,HIGH_TITLE_PROFESSION as certMajor from HR_SUB_PERSONNEL where DELETE_FLAG = 'NOT_DELETE' and `STATUS` in ('0', '1')) a LEFT JOIN SYS_ORG c ON a.orgId = c.ID LEFT JOIN SYS_POSITION d ON a.positionId = d.ID where 1 = 1
and a.name like CONCAT('%', #{name}, '%')
and a.status = #{status}
and a.userType = #{userType}
